INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (71, '西奥多·罗斯福', 'Theodore Roosevelt', '1858—1919', '19—20世纪', '美国', '总统', ARRAY['政治家', '美国', '环保'], '美国第26任总统，进步时代的象征。他推动反垄断、自然保护，并以大棒外交塑造了美国的海外形象。', '探险随队', '', 'assets/figures/rooseveltT.jpg', ARRAY['10-27', '09-14'], ARRAY['诞辰 · 1858年10月27日', '继任总统 · 1901年9月14日'], ARRAY['birth', 'event'], '他进荒野考察，背夫里有你一个，帐篷也是你搭的。', ARRAY['探险随队', '反垄断线人'], ARRAY['他进荒野考察，背夫里有你一个，帐篷也是你搭的。', '那些托拉斯的黑账，是你递到他手上，才掀起了反垄断。']),
  (72, '阿基米德', 'Archimedes', '约前287—前212', '古希腊', '叙拉古', '数学家', ARRAY['科学家', '希腊', '数学'], '古希腊数学家与发明家。他发现浮力定律与杠杆原理，并在叙拉古保卫战中设计防御机械，被誉为古代科学巨擘。', '叙拉古匠师', '', 'assets/figures/archimedes.jpg', ARRAY['01-01', '06-01'], ARRAY['诞辰（约） · 前287年', '叙拉古保卫战 · 前213年'], ARRAY['birth', 'event'], '他喊尤里卡那回，浴池是你烧的热水，你比谁都先听见。', ARRAY['叙拉古匠师', '浴室伙计'], ARRAY['他喊尤里卡那回，浴池是你烧的热水，你比谁都先听见。', '守城用的抛石机，图纸你帮他描了无数遍。']),
  (73, '开普勒', 'Johannes Kepler', '1571—1630', '16—17世纪', '德国', '天文学家', ARRAY['科学家', '德国', '天文'], '德国天文学家，行星运动三大定律的提出者。他将以观测为基础的精确轨道带入现代天文学，为牛顿铺路。', '观星助手', '', 'assets/figures/kepler.jpg', ARRAY['12-27', '10-01'], ARRAY['诞辰 · 1571年12月27日', '《新天文学》出版 · 1609年'], ARRAY['birth', 'event'], '他算轨道算到眼花，数据是你看的表，错一位你先发现。', ARRAY['观星助手', '星历抄写'], ARRAY['他算轨道算到眼花，数据是你看的表，错一位你先发现。', '那本星历的抄本，落款是你的名，他笑称你才是合伙。']),
  (74, '拉瓦锡', 'Antoine Lavoisier', '1743—1794', '18世纪', '法国', '化学家', ARRAY['科学家', '法国', '化学'], '法国化学家，现代化学之父。他确立质量守恒、命名氧气，并以定量实验扫清了炼金术的迷雾。', '天平侍者', '', 'assets/figures/lavoisier.jpg', ARRAY['08-26', '04-01'], ARRAY['诞辰 · 1743年8月26日', '《化学基础论》 · 1789年'], ARRAY['birth', 'event'], '他的天平，只有你敢碰，每一次称量你都替他记。', ARRAY['天平侍者', '皇家农场监'], ARRAY['他的天平，只有你敢碰，每一次称量你都替他记。', '皇家农场做实验，场务归你管，兔子与草料都听你的。']),
  (75, '法拉第', 'Michael Faraday', '1791—1867', '19世纪', '英国', '物理学家', ARRAY['科学家', '英国', '物理'], '英国物理学家与化学家，电磁感应的发现者。他的实验为电力时代奠定基石，几乎全靠自学成才。', '实验室杂工', '', 'assets/figures/faraday.jpg', ARRAY['09-22', '08-29'], ARRAY['诞辰 · 1791年9月22日', '发现电磁感应 · 1831年8月29日'], ARRAY['birth', 'event'], '他做电磁感应那回，线圈是你绕的，手被电麻了三次。', ARRAY['实验室杂工', '皇家学会门房'], ARRAY['他做电磁感应那回，线圈是你绕的，手被电麻了三次。', '皇家学会的门，你替他看了一辈子，来宾你比他认得多。']),
  (76, '麦克斯韦', 'James Clerk Maxwell', '1831—1879', '19世纪', '英国', '物理学家', ARRAY['科学家', '英国', '物理'], '英国物理学家，经典电磁理论的集大成者。他以方程组统一电、磁与光，深刻塑造了现代物理学。', '剑桥助教', '', 'assets/figures/maxwell.jpg', ARRAY['06-13', '11-01'], ARRAY['诞辰 · 1831年6月13日', '电磁理论成型 · 1865年'], ARRAY['birth', 'event'], '他在剑桥讲课，板书你替他擦也替他写。', ARRAY['剑桥助教', '方程誊录'], ARRAY['他在剑桥讲课，板书你替他擦也替他写。', '那组电磁方程的手稿，最后一遍是你整理的，涂改最多那页是你的。']),
  (77, '孟德尔', 'Gregor Mendel', '1822—1884', '19世纪', '奥地利', '生物学家', ARRAY['科学家', '奥地利', '生物'], '奥地利修道士与生物学家，遗传学的奠基人。他通过豌豆实验揭示了性状遗传的基本规律。', '修道院园丁', '', 'assets/figures/mendel.jpg', ARRAY['07-20', '02-08'], ARRAY['诞辰 · 1822年7月20日', '豌豆实验报告 · 1865年2月8日'], ARRAY['birth', 'event'], '修道院后园的豌豆，是你替他一垄垄种的，浇水也归你。', ARRAY['修道院园丁', '豌豆记录员'], ARRAY['修道院后园的豌豆，是你替他一垄垄种的，浇水也归你。', '那些性状的数据，记在你这本子里，他临终前还来翻。']),
  (78, '拉斐尔', 'Raphael', '1483—1520', '文艺复兴', '意大利', '画家', ARRAY['画家', '意大利', '文艺复兴'], '意大利文艺复兴三杰之一。他以和谐的构图与优雅的圣母像著称，英年早逝却影响深远。', '画室学徒', '', 'assets/figures/raphael.jpg', ARRAY['04-06', '09-01'], ARRAY['诞辰 · 1483年4月6日', '任圣彼得大教堂建筑师 · 1514年'], ARRAY['birth', 'event'], '他画圣母，你磨了一整年颜料，手上的石青怎么也洗不掉。', ARRAY['画室学徒', '教皇府裁缝'], ARRAY['他画圣母，你磨了一整年颜料，手上的石青怎么也洗不掉。', '教皇府的礼服，尺寸你最清楚，逢节庆都是你赶制的。']),
  (79, '提香', 'Titian', '约1490—1576', '文艺复兴', '意大利', '画家', ARRAY['画家', '威尼斯', '文艺复兴'], '威尼斯画派巨匠，以绚烂的色彩与肖像画闻名。他服务多任教皇与君主，艺术生涯横跨十六世纪大半。', '威尼斯船工', '', 'assets/figures/titian.jpg', ARRAY['08-01', '04-01'], ARRAY['诞辰（约） · 约1490年', '任宫廷画家 · 1533年'], ARRAY['birth', 'event'], '威尼斯的运河，你摇橹送他过的最多，画箱都让你搬。', ARRAY['威尼斯船工', '颜料调配'], ARRAY['威尼斯的运河，你摇橹送他过的最多，画箱都让你搬。', '他那招牌的红色，配方只有你俩知道，调色的手归你。']),
  (80, '维米尔', 'Johannes Vermeer', '1632—1675', '17世纪', '荷兰', '画家', ARRAY['画家', '荷兰', '黄金时代'], '荷兰黄金时代画家，以静谧的光影与室内场景著称。《戴珍珠耳环的少女》使他名垂后世。', '代尔夫特窗下', '', 'assets/figures/vermeer.jpg', ARRAY['10-31', '12-01'], ARRAY['诞辰 · 1632年10月31日', '入圣路加行会 · 1653年'], ARRAY['birth', 'event'], '你住他楼下，窗里的光你最熟悉，常替他挡住过路的人影。', ARRAY['代尔夫特窗下', '暗室配色'], ARRAY['你住他楼下，窗里的光你最熟悉，常替他挡住过路的人影。', '他画里的蓝，调色归你管，靛蓝你磨了一罐又一罐。'])
